#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <limits.h>

/*  The original binary implements a tiny “perfect‑number” utility.
 *  It expects a single command‑line argument (a decimal integer n).
 *  Behaviour (exactly as observed in the decompiled state machine):
 *
 *    * No argument supplied                → prints "NO_INPUT"
 *    * Argument cannot be parsed as a
 *      non‑negative integer (or contains
 *      extra characters)                  → prints "BAD_INPUT"
 *    * n <= 0                              → prints "BAD_INPUT"
 *    * n > 1 000 000                       → prints "OUT_OF_RANGE"
 *
 *    * Otherwise it computes the sum of the proper
 *      divisors of n (i.e. all positive integers < n
 *      that divide n).  Let that sum be `s`.
 *
 *        s == n   → prints "n=%ld sum=%ld perfect\n"
 *        s  > n   → prints "n=%ld sum=%ld abundant\n"
 *        s  < n   → prints "n=%ld sum=%ld deficient\n"
 *
 *  The messages and formatting are taken verbatim from the
 *  strings embedded in the original binary.
 */

static long sum_proper_divisors(long n)
{
    long sum = 0;
    for (long d = 1; d * d <= n; ++d) {
        if (n % d == 0) {
            long other = n / d;
            if (d != n)          sum += d;          /* d is a proper divisor */
            if (other != d && other != n) sum += other; /* the paired divisor */
        }
    }
    return sum;
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    errno = 0;
    long n = strtol(argv[1], &endptr, 10);

    /* strtol failed to consume any characters */
    if (endptr == argv[1]) {
        puts("BAD_INPUT");
        return 0;
    }

    /* extra characters after the number */
    if (*endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* overflow / underflow detection */
    if (errno == ERANGE || n > LONG_MAX || n < LONG_MIN) {
        puts("BAD_INPUT");
        return 0;
    }

    if (n <= 0) {
        puts("BAD_INPUT");
        return 0;
    }

    if (n > 1000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    long s = sum_proper_divisors(n);

    if (s == n) {
        printf("n=%ld sum=%ld perfect\n", n, s);
    } else if (s > n) {
        printf("n=%ld sum=%ld abundant\n", n, s);
    } else {
        printf("n=%ld sum=%ld deficient\n", n, s);
    }

    return 0;
}
